const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const groups = JSON.parse(await fs.readFile(S+"\\_GIG50_FINAL.json","utf8"));

// 剔除明确不可用的
const DEAD = ["打不开","反爬拦截","服务器错误","空页面","需登录/营销"];
const clean = [];
let removed = [];
for (const g of groups) {
  const ok = [];
  for (const it of g.items) {
    const st = String(it.status);
    const isDead = DEAD.some(d=>st.includes(d));
    if (isDead) { removed.push({host:it.host, status:st, cat:g.cat}); }
    else ok.push(it);
  }
  if (ok.length) clean.push({ cat: g.cat, items: ok });
}
const total = clean.reduce((s,g)=>s+g.items.length,0);
await fs.writeFile(S+"\\_GIG50_CLEAN.json", JSON.stringify(clean,null,1), "utf8");
return {
  cleanTotal: total,
  groups: clean.map(g=>g.cat+" : "+g.items.length+" → "+g.items.map(i=>i.host).join(", ")),
  removedCount: removed.length,
  removed: removed
};
